head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = "";
scwin.isurCd  = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function(e) {
    try {
        // 초기화함수
        scwin.init();

        await scwin.list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92016.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.secugrpId = $c.data.getParameter("secugrpId");
    scwin.isurCd   = $c.data.getParameter("isurCd");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description 더블클릭
 * @param {Number} rowIndex 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex) {
    try {
        let rowData  = dlt_isuListRes.getRowJSON(rowIndex)
        await scwin.serParam(rowData);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92016.grd_IsuInst_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 확인
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function (e) {
    try {
        await scwin.serParam(dlt_isuListRes.getRowJSON(dlt_isuListRes.getRowPosition()));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92016.btn_confirm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name list
 * @description 종목 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function() {

    dma_searchReq.set("secugrpId", scwin.secugrpId);
    dma_searchReq.set("isurCd", scwin.isurCd);

    const sbmOptions = {
            id: "sbm_isuList",
            action: "/api/listing/common/pop/etc/newlist-isu-by-isur/select-list",
            method: "get",
            ref: "dma_searchReq",
            target: "dlt_isuListRes=body"
    };

    $c.sbm.executeDynamic(sbmOptions);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name serParam
 * @description fn_serParam
 * @param {*} rowData rowData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.serParam = async function(rowData) {
await $c.win.closePopup(rowData);
};
